{"task_id": "T35", "code": "def solve(grid):
    """Count islands in a possibly jagged grid of 0/1 values.
    Uses 4-directional adjacency. Works even if rows have different lengths.
    """
    if not grid:
        return 0
    n = len(grid)
    visited = [ [False]*len(row) for row in grid ]
    def bfs(r, c):
        from collections import deque
        q = deque([(r, c)])
        visited[r][c] = True
        while q:
            i, j = q.popleft()
            # neighbors up, down, left, right
            for di, dj in ((1,0),(-1,0),(0,1),(0,-1)):
                ni, nj = i+di, j+dj
                if 0 <= ni < n and 0 <= nj < len(grid[ni]) and not visited[ni][nj] and grid[ni][nj] == 1:
                    visited[ni][nj] = True
                    q.append((ni, nj))
    count = 0
    for i, row in enumerate(grid):
        for j, val in enumerate(row):
            if val == 1 and not visited[i][j]:
                count += 1
                bfs(i, j)
    return count
"}

