def solve(tokens):
    # Accept any iterable of tokens.
    try:
        toks = list(tokens)
    except Exception:
        return None
    if not toks:
        return None
    stack = []
    ops = {'+', '-', '*', '/'}
    for token in toks:
        if token in ops:
            if len(stack) < 2:
                return None
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            else:  # '/'
                # Truncate toward zero
                stack.append(int(a / b))
        else:
            # Convert to int, ignore errors
            try:
                stack.append(int(token))
            except Exception:
                return None
    return stack[-1] if stack else None

