def solve(grid):
    """Count islands in a possibly ragged binary grid.
    Each cell is 0 or 1. Adjacent cells are up, down, left, right where those
    positions exist (i.e., within the bounds of their respective rows).
    """
    if not grid:
        return 0
    rows = len(grid)
    # visited set of (r,c)
    visited = set()
    def neighbors(r, c):
        # up
        if r - 1 >= 0 and c < len(grid[r - 1]):
            yield r - 1, c
        # down
        if r + 1 < rows and c < len(grid[r + 1]):
            yield r + 1, c
        # left
        if c - 1 >= 0:
            yield r, c - 1
        # right
        if c + 1 < len(grid[r]):
            yield r, c + 1
    def dfs(start_r, start_c):
        stack = [(start_r, start_c)]
        while stack:
            r, c = stack.pop()
            if (r, c) in visited:
                continue
            visited.add((r, c))
            for nr, nc in neighbors(r, c):
                if (nr, nc) not in visited and grid[nr][nc] == 1:
                    stack.append((nr, nc))
    count = 0
    for r, row in enumerate(grid):
        for c, val in enumerate(row):
            if val == 1 and (r, c) not in visited:
                dfs(r, c)
                count += 1
    return count

