    filtered = [ch for ch in s.upper() if ch in roman]
    if not filtered:
        return 0
    total = 0
    i = 0
    n = len(filtered)
    while i < n:
        if i + 1 < n and roman[filtered[i]] < roman[filtered[i + 1]]:
